create extension if not exists pgcrypto;
create type public.app_role as enum ('owner','manager','maintenance','tenant');
create table public.profiles(id uuid primary key references auth.users(id),role public.app_role not null,full_name text not null);
create table public.properties(id uuid primary key default gen_random_uuid(),owner_id uuid not null references public.profiles(id),name text not null,address text not null,jurisdiction_late_fee_cap numeric(10,2) not null check(jurisdiction_late_fee_cap>=0));
create table public.units(id uuid primary key default gen_random_uuid(),property_id uuid not null references public.properties(id) on delete cascade,label text not null);
create table public.leases(id uuid primary key default gen_random_uuid(),unit_id uuid not null references public.units(id),tenant_id uuid not null references public.profiles(id),starts_on date not null,ends_on date not null,monthly_rent numeric(10,2) not null,due_day int not null check(due_day between 1 and 28),grace_period_days int not null default 0,late_fee_type text not null check(late_fee_type in('flat','percent')),late_fee_value numeric(10,2) not null,insurance_expires_on date,active boolean not null default true);
create table public.rent_payments(id uuid primary key default gen_random_uuid(),lease_id uuid not null references public.leases(id),period_start date not null,amount_due numeric(10,2) not null,late_fee_amount numeric(10,2) not null default 0,status text not null check(status in('pending','paid','late')),paid_at timestamptz,provider_reference text unique);
create table public.maintenance_requests(id uuid primary key default gen_random_uuid(),unit_id uuid not null references public.units(id),tenant_id uuid not null references public.profiles(id),description text not null,urgency text not null,trade text not null,status text not null default 'submitted',created_at timestamptz not null default now());
create table public.compliance_flags(id uuid primary key default gen_random_uuid(),lease_id uuid not null references public.leases(id),flag_type text not null,severity text not null,detected_at timestamptz not null default now(),resolved_at timestamptz);
create unique index one_open_flag_per_type on public.compliance_flags(lease_id,flag_type) where resolved_at is null;
create table public.audit_events(id uuid primary key default gen_random_uuid(),actor_id uuid references public.profiles(id),entity_type text not null,entity_id uuid not null,action text not null,payload jsonb not null default '{}',solana_signature text,created_at timestamptz not null default now());
alter table public.profiles enable row level security; alter table public.leases enable row level security; alter table public.rent_payments enable row level security; alter table public.maintenance_requests enable row level security; alter table public.compliance_flags enable row level security;
create policy "users read own profile" on public.profiles for select using(id=auth.uid());
create policy "tenant reads own lease" on public.leases for select using(tenant_id=auth.uid());
create policy "tenant reads own payments" on public.rent_payments for select using(exists(select 1 from public.leases where leases.id=rent_payments.lease_id and leases.tenant_id=auth.uid()));
create policy "tenant creates own requests" on public.maintenance_requests for insert with check(tenant_id=auth.uid());
create policy "tenant reads own requests" on public.maintenance_requests for select using(tenant_id=auth.uid());
create or replace function public.reject_excessive_late_fee() returns trigger language plpgsql as $$ declare cap numeric; computed numeric; begin select p.jurisdiction_late_fee_cap into cap from public.units u join public.properties p on p.id=u.property_id where u.id=new.unit_id; computed:=case when new.late_fee_type='flat' then new.late_fee_value else new.monthly_rent*new.late_fee_value/100 end; if computed>cap then raise exception 'Configured late fee exceeds jurisdiction cap'; end if; return new; end $$;
create trigger enforce_late_fee_cap before insert or update on public.leases for each row execute function public.reject_excessive_late_fee();